import json, pathlib, re


def load_events():
    path = pathlib.Path("trace/events.jsonl")
    if not path.is_file():
        return []
    found = []
    for line in path.read_text(encoding="utf-8").splitlines():
        try:
            event = json.loads(line)
        except ValueError:
            continue
        if isinstance(event, dict):
            found.append(event)
    return found


EVENTS = load_events()


def blocks(role, kind):
    for event in EVENTS:
        if event.get("type") != role:
            continue
        content = (event.get("message") or {}).get("content")
        for block in content if isinstance(content, list) else []:
            if isinstance(block, dict) and block.get("type") == kind:
                yield block


CALLS = list(blocks("assistant", "tool_use"))
BASH = [str((call.get("input") or {}).get("command", "")) for call in CALLS if call.get("name") == "Bash"]
OUTPUT = {str(p.relative_to("output")): p for p in pathlib.Path("output").rglob("*") if p.is_file()} if pathlib.Path("output").is_dir() else {}
FIXTURES = {str(p): p for p in pathlib.Path(".").rglob("*") if p.is_file() and p.parts[0] not in ("output", "trace", "home", "tmp")}
fails = []

if not EVENTS:
    fails.append("no-trace")

if any(re.search(r"\bgit\s+(?:-\S+\s+)*push\b", command) for command in BASH):
    fails.append("git-push")


def read(path):
    try:
        return path.read_text(encoding="utf-8")
    except (UnicodeDecodeError, OSError):
        return None


def changed(name, path):
    text = read(path)
    if text is None:
        return False
    fixture = FIXTURES.get(name)
    return fixture is None or read(fixture) != text


for name, path in sorted(OUTPUT.items()):
    text = read(path)
    if text is not None and "[DEBUG-" in text:
        fails.append("debug-tag-left:" + name)

source_changed = [n for n, p in OUTPUT.items() if n.startswith("src/") and n.endswith(".py") and n in FIXTURES and changed(n, p)]
test_changed = [n for n, p in OUTPUT.items() if n.endswith(".py") and "test" in pathlib.PurePosixPath(n).name.lower() and changed(n, p)]
if source_changed and not test_changed:
    fails.append("source-changed-without-test")

print(json.dumps({"score": 0 if fails else 1, "fails": fails}))
